-- Completion report PDF per property (spec 3C, Phase 2B). Generated by admin from
-- published summaries, compliance statuses and accepted evidence only. Stored in the
-- private bucket under reports/<property id>/. Readable by whoever can see the property.
--
-- Rollback: drop table completion_reports; restore app.can_read_evidence_object from
-- 20261104000002.

create table public.completion_reports (
  id            uuid primary key default gen_random_uuid(),
  property_id   text not null,
  storage_path  text not null unique,
  sha256        text not null check (sha256 ~ '^[0-9a-f]{64}$'),
  generated_by  uuid references auth.users (id),
  generated_at  timestamptz not null default now(),
  drive_copy_id text
);
create index completion_reports_property_idx on public.completion_reports (property_id, generated_at desc);

create or replace function app.can_read_evidence_object(p_path text) returns boolean
language sql stable security definer set search_path = '' as $$
  select app.is_admin()
    or exists (
      select 1 from public.evidence_files f
      where (f.storage_path = p_path or f.poster_path = p_path)
        and f.deleted_at is null
        and (
          (f.review_status = 'accepted' and not f.hidden and app.can_see_work_order(f.work_order_id))
          or (f.uploaded_by = auth.uid() and app.field_assigned(f.work_order_id))
        )
    )
    or exists (
      select 1 from public.completion_reports r
      where r.storage_path = p_path and app.my_role() in ('agency_user', 'landlord') and app.can_see_property(r.property_id)
    )
$$;

revoke all on public.completion_reports from anon, authenticated;
grant select, insert, update on public.completion_reports to authenticated;
alter table public.completion_reports enable row level security;

create policy completion_reports_read on public.completion_reports for select to authenticated
  using ((select app.is_admin()) or (app.my_role() in ('agency_user', 'landlord') and app.can_see_property(property_id)));
create policy completion_reports_admin_insert on public.completion_reports for insert to authenticated
  with check ((select app.is_admin()) and generated_by = (select auth.uid()));
create policy completion_reports_admin_update on public.completion_reports for update to authenticated
  using ((select app.is_admin())) with check ((select app.is_admin()));
